setup.raw:
- name: Use physical temporary paths for synthetic project fixtures
  run: |
    node --input-type=module <<'NODE'
    import {appendFileSync, realpathSync} from 'node:fs';
    import {tmpdir} from 'node:os';
    // The native Windows resolver also expands 8.3 names.
    const root = realpathSync.native(tmpdir());
    for (const name of ['TEMP', 'TMP', 'TMPDIR']) {
      appendFileSync(process.env.GITHUB_ENV, `${name}=${root}\n`);
    }
    NODE

