setup.raw:
- name: Locate the built debug CLI for adapter conformance
  run: |
    node --input-type=module <<'NODE'
    import { accessSync, appendFileSync, constants } from 'node:fs';
    import { resolve, sep } from 'node:path';
    const binary = resolve('target/debug', process.platform === 'win32' ? 'lekalo.exe' : 'lekalo').split(sep).join('/');
    accessSync(binary, constants.X_OK);
    appendFileSync(process.env.GITHUB_ENV, `LEKALO_DEBUG_BIN=${binary}\n`);
    NODE

